#include <bits/stdc++.h>
using namespace std;

struct PairHash {
    size_t operator()(const pair<long long, long long> &p) const {
        unsigned long long x = p.first * 0x9E3779B97F4A7C15ULL ^ (p.second + 0x632BE59BD9B4E019ULL);
        x ^= x >> 31;
        x *= 0xBF58476D1CE4E5B9ULL;
        return x ^ (x >> 29);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> a(n), prefix(n + 1, 0);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        prefix[i + 1] = prefix[i] + a[i];
    }
    // Left end l is stored under (a[l], prefix[l] + 2*a[l]); a right end r matches (a[r], prefix[r]).
    unordered_map<pair<long long, long long>, long long, PairHash> counts;
    counts.reserve(2 * n);
    long long answer = 0;
    for (int right = 2; right < n; right++) {
        int left = right - 2;
        counts[{a[left], prefix[left] + 2 * a[left]}]++;
        auto it = counts.find({a[right], prefix[right]});
        if (it != counts.end()) answer += it->second;
    }
    cout << answer << '\n';
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream is = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int rb() throws IOException {
        if (ptr == len) {
            len = is.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = rb();
        while (c != '-' && (c < '0' || c > '9')) c = rb();
        boolean neg = c == '-';
        if (neg) c = rb();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = rb();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }


    record Key(long value, long target) {}

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n], prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            a[i] = nextLong();
            prefix[i + 1] = prefix[i] + a[i];
        }
        // Left end l is stored under (a[l], prefix[l] + 2*a[l]); a right end r matches (a[r], prefix[r]).
        HashMap<Key, Long> counts = new HashMap<>(2 * n);
        long answer = 0;
        for (int right = 2; right < n; right++) {
            int left = right - 2;
            counts.merge(new Key(a[left], prefix[left] + 2 * a[left]), 1L, Long::sum);
            answer += counts.getOrDefault(new Key(a[right], prefix[right]), 0L);
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	c, _ := reader.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = reader.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = reader.ReadByte()
	}
	n := 0
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = reader.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}


func main() {
	n := readInt()
	a, prefix := make([]int, n), make([]int, n+1)
	for i := range a {
		a[i] = readInt()
		prefix[i+1] = prefix[i] + a[i]
	}
	// Left end l is stored under (a[l], prefix[l] + 2*a[l]); a right end r matches (a[r], prefix[r]).
	counts := make(map[[2]int]int, n)
	answer := 0
	for right := 2; right < n; right++ {
		left := right - 2
		counts[[2]int{a[left], prefix[left] + 2*a[left]}]++
		answer += counts[[2]int{a[right], prefix[right]}]
	}
	fmt.Println(answer)
}
